import java.io.*;
import java.util.Scanner;
public class SafeCommandExecutionDemo {
public static void main(String[] args) {
try {
Scanner scanner = new Scanner(System.in);
System.out.print("Enter a command to execute: ");
String command = scanner.nextLine();
// Sanitize and validate user input
if (!command.matches("[a-zA-Z0-9]+")) {
System.out.println("Invalid command");
return;
}
ProcessBuilder processBuilder = new ProcessBuilder("ping", command);
Process process = processBuilder.start();
BufferedReader inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
String inputLine;
while ((inputLine = inputReader.readLine()) != null) {
System.out.println(inputLine);
}
} catch (IOException e) {
e.printStackTrace();
}
}
},Classification: NOT_VULNERABLE. Vulnerability Type: safe

